// Loads the read-only database snapshot (frontend/public/data/*.json, generated by
// scripts/export_static_data.py) on demand. Each file is fetched at most once per
// page load; a failed fetch is retried on the next call.

import {
  indexAtar,
  indexStandards,
  indexWeightings,
  type AtarIndex,
  type RawAtarFile,
  type RawStandardsFile,
  type RawWeightingsFile,
  type StandardsIndex,
  type WeightingsIndex,
} from './engine/dataset';

// Set at build time for GitHub Pages project sites (e.g. "/NCEA-2-ATAR"); empty for a custom domain.
const BASE_PATH = process.env.NEXT_PUBLIC_BASE_PATH ?? '';

function memoizedLoader<Raw, T>(file: string, index: (raw: Raw) => T): () => Promise<T> {
  let promise: Promise<T> | null = null;
  return () => {
    if (!promise) {
      promise = fetch(`${BASE_PATH}/data/${file}`)
        .then((res) => {
          if (!res.ok) throw new Error(`Failed to load ${file}: ${res.status}`);
          return res.json() as Promise<Raw>;
        })
        .then(index)
        .catch((err) => {
          promise = null;
          throw err;
        });
    }
    return promise;
  };
}

export const loadStandards = memoizedLoader<RawStandardsFile, StandardsIndex>('standards.json', indexStandards);
export const loadWeightings = memoizedLoader<RawWeightingsFile, WeightingsIndex>('weightings.json', indexWeightings);
export const loadAtar = memoizedLoader<RawAtarFile, AtarIndex>('atar.json', indexAtar);

/**
 * Warm all data files once the browser is idle, so the first search / calculation
 * doesn't wait on the network. Safe to call repeatedly.
 */
export function prefetchStaticData(): void {
  if (typeof window === 'undefined') return;
  const run = () => {
    // Search data first: it is needed as soon as the user starts typing.
    loadStandards()
      .then(() => Promise.all([loadWeightings(), loadAtar()]))
      .catch(() => { /* retried on demand */ });
  };
  if ('requestIdleCallback' in window) {
    window.requestIdleCallback(run, { timeout: 2000 });
  } else {
    setTimeout(run, 200);
  }
}
